+import { isMessageable } from "./session-bus-presence-store.mjs";
+
+export const ISSUE_WATCH_LIMITS = Object.freeze({ perSession: 50 });
+
+const SLUG = /^([A-Za-z0-9_.-]{1,100})\/([A-Za-z0-9_.-]{1,100})$/;
