+  const hash = text.lastIndexOf("#");
+  const repo = (hash > 0 ? text.slice(0, hash) : String(defaultRepo || "")).trim();
+  const number = (hash >= 0 ? text.slice(hash + 1) : text).trim();
+  const slug = SLUG.exec(repo);
